from qgis.PyQt.QtWidgets import QAction
mw = iface.mainWindow()
act = mw.findChild(QAction, 'mActionSimplifyFeature')
if act is None:
    # フォールバック: テキストで検索
    cands = [(a.objectName(), a.text(), a.isEnabled()) for a in mw.findChildren(QAction) if '簡素化' in (a.text() or '') or 'implify' in (a.objectName() or '')]
    result = {'found': None, 'candidates': cands}
else:
    was_enabled = act.isEnabled()
    act.trigger()
    QgsApplication.processEvents()
    mt = iface.mapCanvas().mapTool()
    result = {'was_enabled': was_enabled, 'checked': act.isChecked(),
              'text': act.text(), 'mapTool': type(mt).__name__ if mt else None}
"}
